function parseAgent(raw){
  let parsed=null, ok=false;
  try { const m=String(raw||'').match(/\{[\s\S]*\}/); parsed=JSON.parse(m?m[0]:raw); ok=true; } catch(e){}
  return {parsed, ok};
}
const {parsed, ok} = parseAgent($json.output);
const p = parsed || {};
return [{ json: {
  title: ok ? 'Ticket triaged (private, local model)' : 'Model did not return valid JSON',
  message: ok
    ? `Category: ${p.category}\nUrgency: ${p.urgency}\n\nSummary:\n${p.summary}\n\nDraft reply:\n${p.draft_reply}`
    : String($json.output)
}}];

// Set MODEL to the EXACT name you use everywhere (write-up, workflow, README)
const MODEL = 'llama3.2:3b';
const tests = $('Test Emails').all();

function parseAgent(raw){
  let parsed=null, ok=false;
  try { const m=String(raw||'').match(/\{[\s\S]*\}/); parsed=JSON.parse(m?m[0]:raw); ok=true; } catch(e){}
  return {parsed, ok};
}
return $input.all().map((item, i) => {
  const t = tests[i].json;
  const {parsed, ok} = parseAgent(item.json.output);
  const steps = item.json.intermediateSteps || [];
  const toolCalled = steps.length > 0;
  const gotCat = parsed ? String(parsed.category||'').toLowerCase().trim() : null;
  const gotUrg = parsed ? String(parsed.urgency||'').toLowerCase().trim() : null;
  return { json: {
    model: MODEL, id: t.id, order_id: t.order_id,
    expected_category: t.expected_category, got_category: gotCat, category_correct: gotCat === t.expected_category,
    expected_urgency: t.expected_urgency, got_urgency: gotUrg, urgency_correct: gotUrg === t.expected_urgency,
    json_valid: ok, tool_called: toolCalled,
    tool_call_ok: toolCalled && JSON.stringify(steps).includes(t.order_id),
    summary: parsed ? parsed.summary : null, draft_reply: parsed ? parsed.draft_reply : null,
    raw_output: item.json.output
  } };
});

const rows = $input.all().map(i => i.json);
const n = rows.length;
const c = k => rows.filter(r => r[k] === true).length;
return [{ json: {
  model: rows[0]?.model, emails: n,
  category_accuracy: c('category_correct') + '/' + n,
  urgency_accuracy: c('urgency_correct') + '/' + n,
  tool_call_success: c('tool_call_ok') + '/' + n,
  valid_json: c('json_valid') + '/' + n
} }];

